function speak(text:string,lang:Lang){if(!('speechSynthesis' in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=lang==='mr'?'mr-IN':lang==='hi'?'hi-IN':'en-IN';u.rate=.9;window.speechSynthesis.speak(u)}
function Shell({children}:{children:ReactNode}){return <main className="min-h-[calc(100vh-64px)] bg-[#fefff3] dark:bg-gray-950"><div className="max-w-3xl mx-auto px-4 sm:px-6 py-5">{children}</div></main>}
function Header({dark,setDark,lang,setLang,screen}:{dark:boolean;setDark:(v:boolean)=>void;lang:Lang;setLang:(v:Lang)=>void;screen:string}){return <header className="sticky top-0 z-40 h-16 border-b border-gray-200/80 dark:border-gray-800 bg-[#fefff3]/95 dark:bg-gray-950/95 backdrop-blur"><div className="max-w-3xl mx-auto h-full px-4 sm:px-6 flex items-center justify-between"><div className="flex items-center gap-2.5"><div className="w-9 h-9 rounded-xl bg-[#77DD76] flex items-center justify-center">🌿</div><div><div className="font-bold text-base leading-none">Nidaan</div><div className="text-[11px] text-gray-500 dark:text-gray-400 mt-1">{I18N[lang].patientIntake}</div></div></div>{!['welcome','success','phone'].includes(screen)&&<div className="flex items-center gap-2"><select value={lang} onChange={e=>setLang(e.target.value as Lang)} className="h-9 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 px-2 text-xs outline-none"><option value="en">English</option><option value="mr">मराठी</option><option value="hi">हिन्दी</option></select><button onClick={()=>setDark(!dark)} className="w-9 h-9 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900">{dark?'☀️':'🌙'}</button></div>}</div></header>}
function Primary({children,onClick,disabled=false}:{children:ReactNode;onClick:()=>void;disabled?:boolean}){return <button disabled={disabled} onClick={onClick} className="w-full h-11 rounded-xl bg-[#77DD76] text-gray-950 px-5 font-bold text-sm shadow-sm hover:bg-[#69d568] disabled:opacity-40 disabled:cursor-not-allowed transition">{children}</button>}
function Ghost({children,onClick}:{children:ReactNode;onClick:()=>void}){return <button onClick={onClick} className="h-11 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 px-5 font-semibold text-sm text-gray-700 dark:text-gray-200 hover:border-[#77DD76]">{children}</button>}
function TextInput({value,onChange,placeholder,onKeyDown}:{value:string;onChange:(v:string)=>void;placeholder:string;onKeyDown?:(e:React.KeyboardEvent<HTMLInputElement>)=>void}){return <input value={value} onChange={e=>onChange(e.target.value)} onKeyDown={onKeyDown} placeholder={placeholder} className="w-full h-12 border border-gray-200 dark:border-gray-700 rounded-xl px-4 bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100 outline-none focus:border-[#77DD76]"/>}
function TextArea({value,onChange,placeholder,rows=3}:{value:string;onChange:(v:string)=>void;placeholder:string;rows?:number}){return <textarea rows={rows} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} className="w-full border border-gray-200 dark:border-gray-700 rounded-xl p-4 bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100 outline-none focus:border-[#77DD76] resize-none text-sm"/>}
function VoiceAnswer({lang,onTranscript}:{lang:Lang;onTranscript:(text:string)=>void}){
 const [listening,setListening]=useState(false); const [message,setMessage]=useState('');
 const start=()=>{
  const SpeechRecognition=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;
  if(!SpeechRecognition){setMessage('Voice recognition is not supported in this browser. Please use Chrome or choose Touch mode.');return}
  const r=new SpeechRecognition(); r.lang=lang==='mr'?'mr-IN':lang==='hi'?'hi-IN':'en-IN'; r.interimResults=false; r.continuous=false;
  r.onstart=()=>{setListening(true);setMessage('Listening…')}; r.onend=()=>setListening(false);
  r.onerror=()=>{setListening(false);setMessage('Could not hear you. Please try again.')};
  r.onresult=(e:any)=>{const text=e.results?.[0]?.[0]?.transcript||'';onTranscript(text);setMessage(text?`Captured: ${text}`:'No answer captured. Please try again.')}; r.start();
 };
 return <div className="rounded-2xl border border-dashed border-[#5abb59] bg-[#9AE79C]/10 p-5 text-center">
  <button onClick={start} disabled={listening} className="mx-auto w-16 h-16 rounded-full bg-[#77DD76] text-2xl shadow-sm disabled:opacity-50">{listening?'⏺':'🎙️'}</button>
  <p className="mt-3 text-sm font-semibold">{listening?'Listening…':'Tap to answer by voice'}</p>
  <p className="mt-1 text-xs text-gray-500">{message||'Speak your answer in the selected language. No typing is needed.'}</p>
 </div>
}
function VoiceChoice({lang,options,multi,onSelect}:{lang:Lang;options:string[];multi:boolean;onSelect:(values:string[])=>void}){
 const [captured,setCaptured]=useState('');
 const choose=(text:string)=>{
  setCaptured(text);
  const normalized=text.toLocaleLowerCase();
  const matches=options.filter(option=>normalized.includes(option.toLocaleLowerCase()));
  if(matches.length) onSelect(multi?matches:[matches[0]]);
 };
 return <div className="space-y-3"><VoiceAnswer lang={lang} onTranscript={choose}/><p className="text-center text-xs text-gray-500">{captured?`Heard: ${captured}`:'Say one of the displayed answer choices clearly.'}</p><div className="flex flex-wrap justify-center gap-2">{options.map(option=><span key={option} className="rounded-full border border-gray-200 dark:border-gray-700 px-3 py-1 text-xs text-gray-500">{option}</span>)}</div></div>
}
function Chip({label,selected,onClick,multi=false}:{label:string;selected:boolean;onClick:()=>void;multi?:boolean}){return <button onClick={onClick} className={`w-full min-h-[50px] rounded-xl border px-4 py-2.5 flex items-center gap-3 text-left text-sm font-medium transition ${selected?'border-[#5abb59] bg-[#9AE79C]/25':'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 hover:border-[#77DD76]'}`}><span className={`shrink-0 w-5 h-5 ${multi?'rounded-md':'rounded-full'} border flex items-center justify-center text-xs ${selected?'border-[#5abb59] bg-[#77DD76] text-white':'border-gray-300 dark:border-gray-600'}`}>{selected?'✓':''}</span>{label}</button>}
function Progress({section,index,total,lang}:{section:string;index:number;total:number;lang:Lang}){const sections=['Chief Complaint','History of Present Illness','Medical & Surgical History','Family History','Personal & Social History','Dashavidha Pariksha'];const pos=sections.indexOf(section);return <><div className="border-b border-gray-200 dark:border-gray-800 bg-white/80 dark:bg-gray-900/80"><div className="max-w-3xl mx-auto px-4 sm:px-6 py-2.5 flex gap-3 overflow-x-auto">{sections.slice(0,pos+1).map((s,i)=><span key={s} className={`shrink-0 text-[11px] font-bold flex items-center gap-1.5 ${i===pos?'text-[#3d8c3c]':'text-gray-400'}`}><i className="w-1.5 h-1.5 rounded-full bg-[#77DD76]"/>{sectionLabel(s,lang)}</span>)}<span className="ml-auto shrink-0 text-[11px] text-gray-400">{index}/{total}</span></div></div></>}
function sectionLabel(section:string,lang:Lang){const m:Record<Lang,Record<string,string>>={en:{'Chief Complaint':'Chief Complaint','History of Present Illness':'History of Present Illness','Medical & Surgical History':'Medical & Surgical History','Family History':'Family History','Personal & Social History':'Personal & Social History','Dashavidha Pariksha':'Dashavidha Pariksha'},mr:{'Chief Complaint':'मुख्य तक्रार','History of Present Illness':'सध्याच्या आजाराचा इतिहास','Medical & Surgical History':'वैद्यकीय व शस्त्रक्रिया इतिहास','Family History':'कौटुंबिक इतिहास','Personal & Social History':'वैयक्तिक व सामाजिक इतिहास','Dashavidha Pariksha':'दशविध परीक्षा'},hi:{'Chief Complaint':'मुख्य शिकायत','History of Present Illness':'वर्तमान बीमारी का इतिहास','Medical & Surgical History':'चिकित्सीय व सर्जिकल इतिहास','Family History':'पारिवारिक इतिहास','Personal & Social History':'व्यक्तिगत व सामाजिक इतिहास','Dashavidha Pariksha':'दशविध परीक्षा'}};return m[lang][section]||section}
function QTitle({q,lang,index,total}:{q:Question;lang:Lang;index:number;total:number}){const d=q.section==='Dashavidha Pariksha'?(dashText[lang][String(q.id)]||dashText.en[String(q.id)]):(questionText[lang][String(q.id)]||questionText.en[String(q.id)]);return <div className="flex items-start gap-3 mb-5"><div className="flex-1"><div className="text-[11px] font-bold tracking-wide text-[#3d8c3c] uppercase mb-1.5">{I18N[lang].q} {q.number}</div><h2 className="text-[1.28rem] md:text-[1.4rem] font-semibold leading-snug text-gray-900 dark:text-gray-50">{d.title}</h2></div><button onClick={()=>speak(d.title,lang)} className="shrink-0 w-10 h-10 rounded-full border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 flex items-center justify-center">🔊</button></div>}

function App(){
 const path=window.location.pathname; const [dark,setDark]=useState(false); const [lang,setLang]=useState<Lang>('en');
 useEffect(()=>{document.documentElement.classList.toggle('dark',dark)},[dark]); useEffect(()=>()=>window.speechSynthesis?.cancel(),[])
 if(path.startsWith('/mobile-upload')) return <MobileUpload lang={lang} setLang={setLang}/>
 return <Kiosk dark={dark} setDark={setDark} lang={lang} setLang={setLang}/>
}
function Kiosk({dark,setDark,lang,setLang}:{dark:boolean;setDark:(v:boolean)=>void;lang:Lang;setLang:(v:Lang)=>void}){
 const t=I18N[lang]; const [screen,setScreen]=useState<'welcome'|'mode'|'verification'|'question'|'dash-choice'|'dash-question'|'documents'|'review'|'consent'|'success'|'emergency'>('welcome'); const [mode,setMode]=useState<Mode>('touch'); const [form,setForm]=useState<FormData>(initialForm); const [index,setIndex]=useState(0); const [dashIndex,setDashIndex]=useState(0); const [patient,setPatient]=useState<SyntheticPatient|null>(null); const [abha,setAbha]=useState(''); const [lookupError,setLookupError]=useState(''); const [checking,setChecking]=useState(false); const [detail,setDetail]=useState(''); const [token,setToken]=useState(''); const [submitError,setSubmitError]=useState(''); const [uploadToken,setUploadToken]=useState(''); const [uploadUrl,setUploadUrl]=useState(''); const [expiresAt,setExpiresAt]=useState(0); const [docs,setDocs]=useState<UploadedDocument[]>([]); const [qrError,setQrError]=useState(''); const [emergencyToken,setEmergencyToken]=useState(''); const [emergencyError,setEmergencyError]=useState(''); const [emergencySubmitting,setEmergencySubmitting]=useState(false);
 const current=questions[index], dashCurrent=dashQuestions[dashIndex]; const qText=questionText[lang][String(current?.id)]||questionText.en[String(current?.id)]; const dText=dashText[lang][String(dashCurrent?.id)]||dashText.en[String(dashCurrent?.id)];
 const checkAbha=async()=>{setLookupError('');setPatient(null);setChecking(true);try{const r=await lookupSyntheticAbha(abha);if(!r.exists||!r.patient)setLookupError(r.error||t.notFound);else setPatient(r.patient)}catch(e){setLookupError(e instanceof Error?e.message:t.notFound)}finally{setChecking(false)}}
 useEffect(()=>{if(screen!=='verification')return;const clean=abha.replace(/\s/g,'');if(/^\d{2}-\d{4}-\d{4}-\d{4}$/.test(clean)){const timer=setTimeout(checkAbha,350);return()=>clearTimeout(timer)}},[abha,screen])
 const setValue=(id:keyof FormData,value:any)=>setForm(f=>({...f,[id]:value} as FormData));
 const toggle=(id:keyof FormData,opt:string)=>setForm(f=>{const old=Array.isArray(f[id])?(f[id] as string[]):[];const none=/^None|^No /.test(opt);const next=none?(old.includes(opt)?[]:[opt]):[...old.filter(x=>!/^None|^No /.test(x)),...(old.includes(opt)?old.filter(x=>x!==opt):[opt])];return {...f,[id]:next} as FormData});
 const continueQ=async()=>{if(current.id==='associatedSymptoms' && form.associatedSymptoms.some(x=>danger.includes(x))){const emergencyForm={...form,redFlagSymptoms:[...form.associatedSymptoms]};setForm(emergencyForm);setEmergencySubmitting(true);setEmergencyError('');setScreen('emergency');try{const r=await submitIntake({form:{...emergencyForm,documents:docs},mode,lang,patientName:patient?.name||'Demo patient',patientId:patient?.abhaId||abha,abhaId:patient?.abhaId||abha});setEmergencyToken(r.token);if(!r.ok)setEmergencyError(r.error||'Unable to transfer the emergency intake.');}catch(e){setEmergencyError(e instanceof Error?e.message:'Unable to transfer the emergency intake.');}finally{setEmergencySubmitting(false);}return} if(current.id==='priorTreatment')setValue('priorTreatmentDetails',detail); if(current.id==='hadSurgery')setValue('surgeryDetails',detail); if(current.id==='allergyMedication')setValue('allergyMedicationDetails',detail); if(current.id==='conditions'||current.id==='familyConditions'||current.id==='addictions')setValue(current.id,form[current.id]); setDetail(''); if(index<questions.length-1)setIndex(index+1);else setScreen('dash-choice')}
 const valid=(q:Question)=>{const v=form[q.id] as any;return q.kind==='text'?String(v||'').trim().length>0:Array.isArray(v)?v.length>0:Boolean(v)}
 const createQr=async()=>{setQrError('');setDocs([]);try{const s=await createDocumentUploadSession();setUploadToken(s.token);setUploadUrl(s.uploadUrl);setExpiresAt(new Date(s.expiresAt).getTime());}catch(e){setQrError(e instanceof Error?e.message:'Unable to create QR session')}}
 useEffect(()=>{if(screen!=='documents'||!form.hasDocuments)return;createQr()},[screen,form.hasDocuments])
 useEffect(()=>{if(!uploadToken)return;const poll=setInterval(async()=>{try{const r=await getDocumentUploadSession(uploadToken);setDocs(r.documents);if(!r.active&&Date.now()<expiresAt)setExpiresAt(new Date(r.expiresAt).getTime())}catch{ /* transient polling failure */}},2000);return()=>clearInterval(poll)},[uploadToken,expiresAt])
 useEffect(()=>{if(!expiresAt)return;const timer=setInterval(()=>{if(Date.now()>=expiresAt){setUploadToken('');setUploadUrl('')}},1000);return()=>clearInterval(timer)},[expiresAt])
 const submit=async()=>{const r=await submitIntake({form:{...form,documents:docs},mode,lang,patientName:patient?.name||'Demo patient',patientId:patient?.abhaId||abha,abhaId:patient?.abhaId||abha});setToken(r.token);setSubmitError(r.error);setScreen('success')}
 const header=(s:string)=><Header dark={dark} setDark={setDark} lang={lang} setLang={setLang} screen={s}/>
 if(screen==='welcome')return <>{header('welcome')}<Shell><div className="py-14 text-center"><div className="mx-auto w-16 h-16 rounded-2xl bg-[#9AE79C]/45 flex items-center justify-center text-3xl mb-5">🌿</div><div className="text-xs font-bold tracking-[.18em] text-[#3d8c3c] uppercase mb-2">Patient Intake Kiosk</div><h1 className="text-3xl md:text-4xl font-semibold mb-3" style={{fontFamily:"'DM Serif Display',Georgia,serif"}}>{t.welcome}</h1><p className="max-w-lg mx-auto text-sm text-gray-500 dark:text-gray-400 mb-7">{t.welcomeDesc}</p><div className="max-w-sm mx-auto"><Primary onClick={()=>setScreen('mode')}>{t.start} →</Primary></div></div></Shell></>
 if(screen==='mode')return <>{header('mode')}<Shell><div className="py-7"><h1 className="text-2xl font-semibold mb-2">{t.modeTitle}</h1><p className="text-sm text-gray-500 mb-6">{t.touchDesc}</p><div className="grid sm:grid-cols-2 gap-3">{[['touch',t.touch,t.touchDesc,'☝️'],['voice',t.voice,t.voiceDesc,'🎤']].map(([id,title,desc,icon])=><button key={id} onClick={()=>setMode(id as Mode)} className={`text-left p-5 rounded-2xl border ${mode===id?'border-[#5abb59] bg-[#9AE79C]/20':'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900'}`}><div className="text-2xl mb-3">{icon}</div><div className="font-bold">{title}</div><div className="text-xs text-gray-500 mt-1">{desc}</div></button>)}</div><div className="flex gap-2 mt-7"><Ghost onClick={()=>setScreen('welcome')}>{t.back}</Ghost><div className="flex-1"><Primary onClick={()=>setScreen('verification')}>{t.continue}</Primary></div></div></div></Shell></>
 if(screen==='verification')return <>{header('verification')}<Shell><div className="py-6"><div className="inline-flex px-3 py-1.5 rounded-full bg-[#9AE79C]/25 text-[#3d8c3c] font-bold text-xs mb-4">Step 1 · {t.verifyTitle}</div><h1 className="text-2xl font-semibold mb-2">{t.verifyTitle}</h1><p className="text-sm text-gray-500 mb-5">{t.verifyDesc}</p><TextInput value={abha} onChange={v=>{setAbha(v);setLookupError('')}} onKeyDown={e=>{if(e.key==='Enter')checkAbha()}} placeholder="12-3456-7890-1234"/><div className="mt-2 flex items-center justify-between"><span className="text-xs text-gray-400">{checking?t.checking:' '}</span><button onClick={checkAbha} disabled={checking} className="text-sm font-bold text-[#3d8c3c] disabled:opacity-40">{t.find}</button></div>{lookupError&&<p className="mt-3 text-sm text-red-600">{lookupError}</p>}{patient&&<div className="mt-5 rounded-2xl border border-[#77DD76] bg-white dark:bg-gray-900 p-5"><div className="text-sm font-bold text-[#3d8c3c] mb-4">✓ {t.found}</div><p className="text-xs text-gray-500 mb-4">{t.verifyHint}</p><div className="grid sm:grid-cols-2 gap-x-6 gap-y-2 text-sm"><p><b>{t.details}:</b> {patient.name}</p><p><b>{t.dob}:</b> {patient.dob}</p><p><b>{t.gender}:</b> {patient.gender}</p><p><b>{t.mobile}:</b> {patient.mobile}</p><p><b>{t.abha}:</b> {patient.abhaId}</p><p><b>{t.abhaAddress}:</b> {patient.abhaAddress}</p><p className="sm:col-span-2"><b>{t.address}:</b> {patient.address}, {patient.district}, {patient.state} - {patient.pincode}</p><p><b>{t.blood}:</b> {patient.bloodGroup||'—'}</p></div><div className="mt-5"><Primary onClick={()=>{setIndex(0);setScreen('question')}}>{t.confirm}</Primary></div></div>}<div className="mt-5"><Ghost onClick={()=>setScreen('mode')}>{t.back}</Ghost></div></div></Shell></>
 if(screen==='question')return <>{header('question')}<Progress section={current.section} index={index+1} total={questions.length} lang={lang}/><Shell><div className="mb-4"><div className="flex justify-between text-xs text-gray-500 mb-2"><span className="font-semibold">{sectionLabel(current.section,lang)}</span><span>{index+1} {t.of} {questions.length}</span></div><div className="h-2 rounded-full bg-gray-200 dark:bg-gray-800 overflow-hidden"><div className="h-full rounded-full bg-[#77DD76]" style={{width:`${((index+1)/questions.length)*100}%`}}/></div></div><div className="rounded-2xl border border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 shadow-sm p-5 md:p-6"><QTitle q={current} lang={lang} index={index} total={questions.length}/>{current.kind==='text'&&(mode==='voice'?<VoiceAnswer lang={lang} onTranscript={v=>setValue(current.id,v)}/>:<TextArea value={String(form[current.id]||'')} onChange={v=>setValue(current.id,v)} placeholder={qText.placeholder||'Type your answer…'} rows={3}/>)} {current.kind!=='text'&&(mode==='voice'?<VoiceChoice lang={lang} options={qText.options||current.options||[]} multi={current.kind==='multi'} onSelect={values=>current.kind==='multi'?setValue(current.id,values):setValue(current.id,values[0]||'')}/>:<div className="flex flex-col gap-2.5">{(qText.options||current.options||[]).map((o,i)=>{const selected=Array.isArray(form[current.id])?(form[current.id] as string[]).includes(current.options?.[i]||o):form[current.id]===current.options?.[i]||form[current.id]===o;return <Chip key={o} label={o} multi={current.kind==='multi'} selected={selected} onClick={()=>current.kind==='multi'?toggle(current.id,current.options?.[i]||o):setValue(current.id,current.options?.[i]||o)}/>})}</div>)}{current.detail&&mode==='touch'&&<div className="mt-3"><TextArea value={detail} onChange={setDetail} placeholder={qText.placeholder||'Additional details…'} rows={2}/></div>}<div className="flex gap-2 mt-5"><Ghost onClick={()=>index>0?setIndex(index-1):setScreen('verification')}>{t.back}</Ghost><div className="flex-1"><Primary disabled={!valid(current)} onClick={continueQ}>{t.continue}</Primary></div></div></div></Shell></>
 if(screen==='emergency')return <>{header('emergency')}<Shell><div className="py-12 text-center"><div className="text-5xl mb-4">⚠️</div><h1 className="text-2xl font-semibold text-red-700 mb-3">{t.emergency}</h1><p className="text-sm text-gray-600 dark:text-gray-300 max-w-lg mx-auto mb-6">{t.emergencyDesc}</p><div className="max-w-lg mx-auto rounded-2xl border-2 border-red-300 bg-red-50 dark:bg-red-950/30 p-5"><p className="font-bold text-red-800 dark:text-red-200">Emergency patient intake sent to the doctor dashboard.</p>{emergencySubmitting&&<p className="text-sm text-red-700 mt-2">Transferring patient information…</p>}{emergencyToken&&<p className="text-sm text-red-700 mt-2">Queue token: <strong>{emergencyToken}</strong></p>}{emergencyError&&<p className="text-sm text-red-800 mt-2">{emergencyError}</p>}<p className="text-xs text-red-700 mt-3">Please inform reception or clinical staff immediately. You do not need to continue the questionnaire.</p></div></div></Shell></>
 if(screen==='dash-choice')return <>{header('dash-choice')}<Progress section="Dashavidha Pariksha" index={15} total={15} lang={lang}/><Shell><div className="py-6"><span className="inline-flex px-3 py-1.5 rounded-full bg-[#9AE79C]/25 text-[#3d8c3c] font-bold text-xs mb-4">🌿 {t.optional}</span><h1 className="text-2xl font-semibold mb-2">{t.dash}</h1><p className="text-sm text-gray-500 mb-5">{t.dashDesc}</p><div className="flex flex-col gap-2.5"><button onClick={()=>{setForm(f=>({...f,wantsDashavidha:true}));setDashIndex(0);setScreen('dash-question')}} className="p-4 rounded-2xl border border-[#5abb59] bg-white dark:bg-gray-900 text-left font-semibold text-sm">🌿 {t.takeDash}</button><button onClick={()=>{setForm(f=>({...f,wantsDashavidha:false}));setScreen('documents')}} className="p-4 rounded-2xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-left text-sm text-gray-600 dark:text-gray-300">{t.skipDash}</button></div><div className="mt-5"><Ghost onClick={()=>{setIndex(14);setScreen('question')}}>{t.back}</Ghost></div></div></Shell></>
 if(screen==='dash-question')return <>{header('dash-question')}<Progress section="Dashavidha Pariksha" index={15} total={15} lang={lang}/><Shell><div className="mb-4"><div className="flex justify-between text-xs text-gray-500 mb-2"><span className="font-semibold">{t.dash} · {t.optional}</span><span>{dashIndex+1} {t.of} 10</span></div><div className="h-2 rounded-full bg-gray-200 dark:bg-gray-800"><div className="h-full rounded-full bg-[#77DD76]" style={{width:`${((dashIndex+1)/10)*100}%`}}/></div></div><div className="rounded-2xl border border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 p-5 md:p-6"><QTitle q={dashCurrent} lang={lang} index={dashIndex} total={10}/>{mode==='voice'?<VoiceChoice lang={lang} options={dText.options} multi={false} onSelect={values=>setValue(dashCurrent.id,values[0]||'')}/>:<div className="flex flex-col gap-2.5">{dText.options.map((o,i)=><Chip key={o} label={o} selected={form[dashCurrent.id]===dashCurrent.options?.[i]||form[dashCurrent.id]===o} onClick={()=>setValue(dashCurrent.id,dashCurrent.options?.[i]||o)}/>)}</div>}<div className="flex gap-2 mt-5"><Ghost onClick={()=>dashIndex>0?setDashIndex(dashIndex-1):setScreen('dash-choice')}>{t.back}</Ghost><div className="flex-1"><Primary disabled={!form[dashCurrent.id]} onClick={()=>dashIndex<9?setDashIndex(dashIndex+1):setScreen('documents')}>{t.continue}</Primary></div></div></div></Shell></>
 if(screen==='documents')return <>{header('documents')}<Shell><div className="py-5"><div className="flex items-center justify-between mb-2"><div><div className="text-[11px] font-bold tracking-wide text-[#3d8c3c] uppercase">Documents</div><h1 className="text-2xl font-semibold mt-1">{t.docsTitle}</h1></div></div><p className="text-sm text-gray-500 mb-5">{t.docsDesc}</p><div className="grid sm:grid-cols-2 gap-2.5"><button onClick={()=>{setForm(f=>({...f,hasDocuments:true}));setDocs([])}} className={`p-4 rounded-xl border text-left text-sm font-semibold ${form.hasDocuments?'border-[#5abb59] bg-[#9AE79C]/20':'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900'}`}>📄 {t.yesDocs}</button><button onClick={()=>{setForm(f=>({...f,hasDocuments:false,documents:[]}));setUploadToken('');setUploadUrl('')}} className={`p-4 rounded-xl border text-left text-sm font-semibold ${form.hasDocuments===false?'border-[#5abb59] bg-[#9AE79C]/20':'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900'}`}>✕ {t.noDocs}</button></div>{form.hasDocuments&&<div className="mt-5 rounded-2xl border border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 p-5 text-center"><h2 className="font-bold text-base mb-1">{t.qrTitle}</h2><p className="text-xs text-gray-500 mb-4">{t.qrDesc}</p>{uploadUrl&&expiresAt>Date.now()?<><img alt="Temporary document upload QR" className="w-48 h-48 mx-auto rounded-xl border border-gray-200 p-2 bg-white" src={`https://api.qrserver.com/v1/create-qr-code/?size=260x260&data=${encodeURIComponent(uploadUrl)}`}/><div className="mt-3 text-[10px] text-gray-500 break-all select-all">{uploadUrl}</div><div className="mt-2 text-xs font-semibold text-[#3d8c3c]">{t.expires} {Math.max(0,Math.ceil((expiresAt-Date.now())/1000))}s</div></>:<div className="py-8"><div className="text-sm text-gray-500">{qrError||t.expired}</div><button onClick={createQr} className="mt-3 text-sm font-bold text-[#3d8c3c]">{t.refresh}</button></div>}<div className="mt-4 text-left">{docs.length?<><div className="text-xs font-bold text-gray-500 uppercase mb-2">{t.uploaded}</div>{docs.map(d=><div key={d.id} className="flex items-center justify-between p-3 rounded-lg bg-[#9AE79C]/15 mb-2 text-sm"><span>📎 {d.name}</span><span className="text-xs text-[#3d8c3c]">✓</span></div>)}<p className="text-xs text-gray-500">{docs.length} {t.documentsReady}</p></>:<p className="text-xs text-gray-400 text-center">{t.waiting}</p>}</div></div>}{!form.hasDocuments&&form.hasDocuments!==null&&<div className="mt-4 p-4 rounded-xl bg-gray-50 dark:bg-gray-900 text-sm text-gray-500">No document upload is needed.</div>}<div className="flex gap-2 mt-5"><Ghost onClick={()=>form.wantsDashavidha?setScreen('dash-question'):setScreen('dash-choice')}>{t.back}</Ghost><div className="flex-1"><Primary disabled={form.hasDocuments===null||(form.hasDocuments===true&&docs.length===0&&expiresAt>Date.now())} onClick={()=>{setForm(f=>({...f,documents:docs}));setScreen('review')}}>{t.review}</Primary></div></div></div></Shell></>
 if(screen==='review')return <>{header('review')}<Shell><div className="py-5"><h1 className="text-2xl font-semibold mb-2">{t.reviewTitle}</h1><p className="text-sm text-gray-500 mb-5">Check the information before submitting.</p><div className="flex flex-col gap-2">{[['Chief Complaint',form.chiefComplaint],['Duration',form.duration],['Onset',form.onset],['Progression',form.progression],['Associated symptoms',form.associatedSymptoms.join(', ')],['Prior treatment',form.priorTreatment.join(', ')],['Medical history',form.conditions.join(', ')],['Surgery / admission',form.hadSurgery],['Allergy / medicines',form.allergyMedicationDetails||form.allergyMedication],['Family history',form.familyConditions.join(', ')],['Hereditary condition',form.familyHereditary],['Diet',form.diet],['Sleep',form.sleep],['Activity',form.physicalActivity],['Tobacco / alcohol / caffeine',form.addictions.join(', ')],['Dashavidha',form.wantsDashavidha?'Completed':'Skipped'],['Documents',docs.map(d=>d.name).join(', ')||'None']].map(([a,b])=><div key={String(a)} className="p-3 rounded-xl border border-gray-100 dark:border-gray-800 bg-white dark:bg-gray-900 flex gap-3 text-sm"><div className="w-36 shrink-0 font-semibold text-gray-500">{a}</div><div>{String(b)||'—'}</div></div>)}</div><div className="flex gap-2 mt-5"><Ghost onClick={()=>setScreen('documents')}>{t.back}</Ghost><div className="flex-1"><Primary onClick={()=>setScreen('consent')}>{t.continue}</Primary></div></div></div></Shell></>
 if(screen==='consent')return <>{header('consent')}<Shell><div className="py-5"><h1 className="text-2xl font-semibold mb-2">{t.consentTitle}</h1><p className="text-sm text-gray-500 mb-5">Please confirm how your intake information may be used.</p><div className="flex flex-col gap-2.5">{[['digital',t.consent1,true],['abha',t.consent2,false],['referral',t.consent3,false]].map(([key,label,required])=><button key={String(key)} onClick={()=>setForm(f=>({...f,consents:{...f.consents,[key as 'digital'|'abha'|'referral']:!f.consents[key as 'digital'|'abha'|'referral']}}))} className={`p-4 rounded-xl border text-left flex gap-3 ${form.consents[key as 'digital'|'abha'|'referral']?'border-[#5abb59] bg-[#9AE79C]/15':'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900'}`}><span className="w-5 h-5 rounded-md border flex items-center justify-center text-xs shrink-0">{form.consents[key as 'digital'|'abha'|'referral']?'✓':''}</span><span className="text-sm flex-1">{label}<small className="block mt-1 text-[10px] font-bold text-gray-400">{required?t.required:t.optionalLabel}</small></span></button>)}</div><div className="flex gap-2 mt-5"><Ghost onClick={()=>setScreen('review')}>{t.back}</Ghost><div className="flex-1"><Primary disabled={!form.consents.digital} onClick={submit}>{t.submit}</Primary></div></div></div></Shell></>
 if(screen==='success')return <>{header('success')}<Shell><div className="py-14 text-center"><div className="w-16 h-16 mx-auto rounded-full bg-white dark:bg-gray-900 border border-[#77DD76] flex items-center justify-center text-3xl">✓</div><h1 className="text-2xl font-semibold mt-5">{t.success}</h1><div className="inline-flex flex-col mt-6 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-2xl px-12 py-7 shadow-sm"><span className="text-[10px] font-bold tracking-[.2em] text-gray-400 uppercase">{t.token}</span><span className="text-5xl font-bold mt-1" style={{fontFamily:"'DM Serif Display',Georgia,serif"}}>{token}</span></div>{submitError&&<p className="text-xs text-gray-500 mt-4">{submitError}</p>}<p className="text-sm text-gray-500 mt-4">{t.tokenNote}</p></div></Shell></>
 return null
}

function MobileUpload({lang,setLang}:{lang:Lang;setLang:(v:Lang)=>void}){
 const t=I18N[lang];
 const params=new URLSearchParams(window.location.search);
 const token=params.get('token')||'';
 const [active,setActive]=useState(true);
 const [files,setFiles]=useState<File[]>([]);
 const [status,setStatus]=useState('');
 const [error,setError]=useState('');
 const [remaining,setRemaining]=useState(180);
 useEffect(()=>{
  if(!token){setActive(false);return}
  let mounted=true;
  const check=async()=>{try{const r=await getDocumentUploadSession(token);if(!mounted)return;setActive(r.active);setRemaining(Math.max(0,Math.ceil((new Date(r.expiresAt).getTime()-Date.now())/1000)))}catch{/* transient network error */}};
  check();const poll=setInterval(check,1000);return()=>{mounted=false;clearInterval(poll)}
 },[token]);
 const addFile=(next:File|null)=>{if(!next)return;setFiles(old=>[...old,next]);setStatus('');setError('')};
 const submitFiles=async()=>{
  if(!files.length||!active)return;
  setStatus(t.uploading);setError('');
  try{
   for(const file of files) await uploadDocumentFromPhone(token,file);
   setStatus(t.uploadDone);setFiles([]);
  }catch(e){setStatus('');setError(e instanceof Error?e.message:'Upload failed')}
 };
 return <div className="min-h-screen bg-[#fefff3] dark:bg-gray-950">
  <header className="h-16 border-b border-gray-200 dark:border-gray-800 flex items-center justify-between px-4">
   <div className="flex items-center gap-2.5"><div className="w-9 h-9 rounded-xl bg-[#77DD76] flex items-center justify-center text-xl">🌿</div><div><div className="font-bold text-base leading-none">Nidaan</div><div className="text-[11px] text-gray-500 mt-1">{t.patientIntake}</div></div></div>
   <select value={lang} onChange={e=>setLang(e.target.value as Lang)} className="h-9 rounded-lg border bg-white px-2 text-xs"><option value="en">English</option><option value="mr">मराठी</option><option value="hi">हिन्दी</option></select>
  </header>
  <div className="max-w-md mx-auto px-4 py-10"><div className="rounded-2xl border border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 p-6 shadow-sm">
   <h1 className="text-2xl font-semibold mb-2">{t.phoneTitle}</h1><p className="text-sm text-gray-500 mb-5">{t.phoneDesc}</p>
   {active?<>
    <div className="p-3 rounded-xl bg-[#9AE79C]/20 text-xs font-semibold text-[#3d8c3c] mb-5">{t.expires} {remaining}s</div>
    <label className="block border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-xl p-8 text-center cursor-pointer hover:border-[#77DD76]"><input type="file" accept="image/*,.pdf,.doc,.docx" className="hidden" onChange={e=>{addFile(e.target.files?.[0]||null);e.currentTarget.value=''}}/><div className="text-3xl mb-2">📄</div><div className="font-semibold text-sm">{t.addFile}</div><div className="text-xs text-gray-500 mt-1">{files.length?`${files.length} file(s) selected`:'Choose one or more files'}</div></label>
    {files.length>0&&<div className="mt-4 space-y-2">{files.map((file,index)=><div key={`${file.name}-${index}`} className="flex items-center justify-between gap-3 rounded-xl border border-gray-200 dark:border-gray-700 p-3"><div className="min-w-0"><div className="text-sm font-semibold break-words">{file.name}</div><div className="text-xs text-gray-500">{Math.ceil(file.size/1024)} KB</div></div><button onClick={()=>setFiles(old=>old.filter((_,i)=>i!==index))} className="shrink-0 rounded-lg border border-red-200 px-3 py-2 text-xs font-semibold text-red-600">{t.removeFile}</button></div>)}</div>}
    <div className="grid grid-cols-2 gap-3 mt-4"><label className="w-full h-11 rounded-xl border border-gray-300 flex items-center justify-center font-bold text-sm cursor-pointer"><input type="file" accept="image/*,.pdf,.doc,.docx" className="hidden" onChange={e=>{addFile(e.target.files?.[0]||null);e.currentTarget.value=''}}/>{t.addFile}</label><button disabled={!files.length||status===t.uploading} onClick={submitFiles} className="w-full h-11 rounded-xl bg-[#77DD76] font-bold text-sm disabled:opacity-40">{status||t.submitFiles}</button></div>
    {error&&<p className="text-sm text-red-600 mt-3">{error}</p>}
   </>:<div className="text-center py-8 text-sm text-gray-500">{t.expired}</div>}
  </div></div>
 </div>
}
export default App
